import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'
import Lightbox from 'yet-another-react-lightbox'
import 'yet-another-react-lightbox/styles.css'

import "../scss/main.scss"

import Header from "../components/Header"

interface ImageSharpEdge {
  node: {
    publicURL: string
    childImageSharp: {
      thumb: IGatsbyImageData
      full: IGatsbyImageData
    }
  }
}

interface PageProps {
  data: {
    images: {
      edges: ImageSharpEdge[]
    }
  }
}

const ArtGalleryTemplate: React.FC<PageProps> = ({ data }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  // Transform images for lightbox
  const lightboxSlides = data.images.edges.map(({ node }) => {
    return {
      src: node.publicURL,
    }
  })

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <Link to="/creations" className="back-link">
          ← Back to Creations
        </Link>
        <h1>Art</h1>
        <p>Expressing creativity through color, texture, and imagination — each piece tells its own story.</p>
        <div className="accent-line"></div>
      </div>
      <div className="masonry-gallery">
        {data.images.edges.map(({ node }, index) => {
          const image = getImage(node.childImageSharp.thumb)
          if (!image) return null

          return (
            <div
              key={index}
              className="gallery-item"
              onClick={() => setLightboxIndex(index)}
            >
              <GatsbyImage
                image={image}
                alt={`Art - Image ${index + 1}`}
                className="gallery-thumb"
              />
            </div>
          )
        })}
      </div>
      <Lightbox
        open={lightboxIndex >= 0}
        close={() => setLightboxIndex(-1)}
        index={lightboxIndex}
        slides={lightboxSlides}
        carousel={{
          finite: false,
          spacing: 0,
          padding: 0
        }}
        animation={{
          fade: 250,
          swipe: 500,
          navigation: 500,
          easing: {
            fade: "ease-out",
            swipe: "ease-in-out",
            navigation: "ease-in-out"
          }
        }}
      />
    </div>
  )
}

export const query = graphql`
  query ArtGalleryTemplateQuery {
    images: allFile(
      filter: { sourceInstanceName: { eq: "art" } }
      sort: { name: ASC }
    ) {
      edges {
        node {
          publicURL
          childImageSharp {
            thumb: gatsbyImageData(
              width: 400
              placeholder: BLURRED
            )
            full: gatsbyImageData(layout: FULL_WIDTH)
          }
        }
      }
    }
  }
`

export default ArtGalleryTemplate
